func dt07_human(seconds: number) {
    line rest = seconds
    line parts = []
    for unit: size in DT07_UNITS {
        if rest >= size {
            parts = append_value("${floor(rest / size)}${unit}")
            rest = rest % size
        }
        if len(parts) == 2 { break }
    }
    return join_text(parts, " ")
}

