const DT11_LOOT = {"a": 70, "b": 25, "c": 5}

func dt11_roll(table: map) {
    line total = 0
    for name: weight in table { total += weight }
    line left = random_number(0, total, integer: false)
    for name: weight in table {
        left -= weight
        if left <= 0 { return name }
    }
    return name
}

process dt11_weights() {
    a = 0
    b = 0
    c = 0
    for i in 1..1000 {
        got = dt11_roll(DT11_LOOT)
        if got == "a" { a += 1 } else if got == "b" { b += 1 } else { c += 1 }
        if remainder(i, 20) == 0 { wait(1) }
    }
    verdict = "мимо"
    if a in 640..760 and b in 190..310 and c in 15..90 { verdict = "похоже" }
    @all send_message("dt11 веса ${verdict} a=${a} b=${b} c=${c}")
}

